insert into public.catalog_libraries(id,code,slug,steward_organization_id,status,created_by)values('f2040000-0000-4000-8000-000000000002','ACTIVATION204_B','activation204-b','b2040000-0000-4000-8000-000000000001','DRAFT','a2040000-0000-4000-8000-000000000001');
create temporary table activation_results(kind text primary key,value jsonb);grant select,insert on activation_results to authenticated;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('PROPOSE1',public.propose_franchise_governance('f2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001','FRANCHISEE','ACT204_1','Territoire 1','النطاق 1','{}',now()-interval'1 day',now()+interval'1 year',100000,'UPFRONT',0,'{"scope":"approved"}','{}','{}','activation204-3@example.invalid',repeat('1',64),'fr-MA','{}','Proposition approuvée 1','activation204-proposal-1'));
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select public.decide_franchise_governance((select(value->>'approval_request_id')::uuid from activation_results where kind='PROPOSE1'),'APPROVE','Approbation indépendante',1,'activation204-approval-1');
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select is((public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'verifiedLegalProof'),'false','no legal proof is invented before first activation');
reset role;
update private.admin_execution_environment_v1 set environment=null where singleton;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),true,'activation204-accept-1')$$,'55000','FRANCHISE_ACTIVATION_ENVIRONMENT_UNCONFIGURED','unconfigured database environment is denied');
reset role;
update private.admin_execution_environment_v1 set environment='PRODUCTION' where singleton;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),true,'activation204-accept-1')$$,'42501','FRANCHISE_DEMO_DEVELOPMENT_ONLY','production cannot execute a simulation');
select throws_ok($$select public.accept_franchise_invitation((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,'activation204-real-1')$$,'55000','FRANCHISE_SIGNED_MANDATE_REQUIRED','production cannot activate unsigned mandate');
reset role;
update private.admin_execution_environment_v1 set environment='DEVELOPMENT' where singleton;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);set local role authenticated;
select throws_ok($$select public.accept_franchise_invitation((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,'activation204-real-1')$$,'42501','FRANCHISE_ACTIVATION_MFA_REQUIRED','real activation requires MFA');
select throws_ok($$select public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),false,'activation204-accept-1')$$,'42501','FRANCHISE_DEMO_DEVELOPMENT_ONLY','simulation requires explicit confirmation');
select throws_ok($$select public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),repeat('e',64),true,'activation204-accept-1')$$,'40001','FRANCHISE_MANDATE_CHANGED','preview source hash is mandatory');
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),true,'activation204-accept-1')$$,'42501','FRANCHISE_INVITATION_ACCEPT_DENIED','sibling organization member is not invitation recipient');
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);set local role authenticated;
select throws_ok($$select public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('f',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),true,'activation204-badtoken')$$,'42501','FRANCHISE_INVITATION_ACCEPT_DENIED','wrong private token cannot activate');
insert into activation_results values('ACTIVE1',public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),true,'activation204-accept-1'));
select is((select value->>'activationMode'from activation_results where kind='ACTIVE1'),'NON_CONTRACTUAL_DEMO','ordinary invited member bootstraps only explicit demo activation');
select is(public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),true,'activation204-accept-1'),(select value from activation_results where kind='ACTIVE1'),'retry returns exact stored evidence without new activation');
reset role;
select ok(private.has_franchise_role((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),array['FRANCHISE_OWNER'],'a2040000-0000-4000-8000-000000000003'),'first owner receives exact mandate assignment');
select is((select count(*)from public.franchise_activation_evidence where invitation_id=(select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1')),1::bigint,'one immutable evidence record');
select ok((select approved_mandate_version_id=(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1')and mandate_hash=(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash')and actor_user_id='a2040000-0000-4000-8000-000000000003'and evidence_snapshot->>'approvalRequestId'=(select value->>'approval_request_id'from activation_results where kind='PROPOSE1')and legal_proof_snapshot is null from public.franchise_activation_evidence where invitation_id=(select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1')),'evidence pins exact approved source hash actor and decision without legal claim');
select ok((select a.entry_fee_minor=b.entry_fee_minor and a.franchisee_share_bps=b.franchisee_share_bps and a.neoxa_share_bps=b.neoxa_share_bps and a.matricia_share_bps=b.matricia_share_bps and a.rights_snapshot=b.rights_snapshot and a.content_hash=b.content_hash from public.franchise_mandate_versions a join public.franchise_activation_evidence e on e.approved_mandate_version_id=a.id join public.franchise_mandate_versions b on b.id=e.active_mandate_version_id where e.invitation_id=(select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1')),'activation preserves approved economics and terms');
select is((select count(*)from public.event_outbox where aggregate_id=(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1')::text and event_type='FranchiseDemoActivatedV1'),1::bigint,'demo event emitted once');
select is((select count(*)from public.event_outbox where aggregate_id=(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1')::text and event_type='FranchiseActivatedV1'),0::bigint,'no contractual activation event for demo');
select throws_ok($$update public.franchise_activation_evidence set mandate_hash=repeat('f',64)where invitation_id=(select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1')$$,'55000','IMMUTABLE_FRANCHISE_ACTIVATION_EVIDENCE','activation evidence cannot be rewritten');
insert into public.organization_member_roles(membership_id,role_code)select'c2040000-0000-4000-8000-000000000005',code from public.role_definitions where scope_type='FRANCHISE';
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('PROPOSE2',public.propose_franchise_governance('f2040000-0000-4000-8000-000000000002','b2040000-0000-4000-8000-000000000001','FRANCHISEE','ACT204_2','Territoire 2','النطاق 2','{}',now()-interval'1 day',now()+interval'1 year',100000,'UPFRONT',0,'{"scope":"approved"}','{}','{}','activation204-4@example.invalid',repeat('2',64),'fr-MA','{}','Proposition approuvée 2','activation204-proposal-2'));
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select public.decide_franchise_governance((select(value->>'approval_request_id')::uuid from activation_results where kind='PROPOSE2'),'APPROVE','Approbation indépendante',1,'activation204-approval-2');
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);set local role authenticated;
insert into activation_results values('ACTIVE2',public.simulate_franchise_invitation_acceptance((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE2'),repeat('2',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE2'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE2'))->>'mandateHash'),true,'activation204-accept-2'));
reset role;
select is((select count(*)from public.organization_member_franchise_assignments where membership_id='c2040000-0000-4000-8000-000000000005'and franchise_id=(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1')and revoked_at is null),6::bigint,'all six legacy roles materialized before second activation');
select ok(not private.has_franchise_role((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE2'),array['FRANCHISE_EXPERT','FRANCHISE_PROVIDER_MANAGER'],'a2040000-0000-4000-8000-000000000005'),'legacy expert and provider manager cannot inherit sibling mandate');
select ok(private.has_franchise_role((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),array['FRANCHISE_EXPERT'],'a2040000-0000-4000-8000-000000000005'),'existing expert assignment remains usable');
update private.admin_execution_environment_v1 set environment='PRODUCTION'where singleton;
select ok(not private.has_franchise_role((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),array['FRANCHISE_OWNER'],'a2040000-0000-4000-8000-000000000003'),'demo role cannot become production access by retagging environment');
update private.admin_execution_environment_v1 set environment=null where singleton;
select ok(not private.has_franchise_role((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),array['FRANCHISE_OWNER'],'a2040000-0000-4000-8000-000000000003'),'demo role denied under unknown environment');
update private.admin_execution_environment_v1 set environment='STAGING'where singleton;
select ok(private.has_franchise_role((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),array['FRANCHISE_OWNER'],'a2040000-0000-4000-8000-000000000003'),'staging retains explicitly simulated access');
select ok(not has_function_privilege('service_role','public.simulate_franchise_invitation_acceptance(uuid,text,integer,uuid,text,boolean,text,uuid)','execute'),'service role cannot impersonate demo signer');
select ok(not has_table_privilege('authenticated','public.franchise_activation_evidence','insert'),'application cannot fabricate legal or demo evidence');
select ok(not has_function_privilege('authenticated','private.accept_franchise_activation_v1(uuid,text,integer,uuid,text,text,boolean,text,uuid)','execute'),'private activation core is not callable by application');


-- Read behavior starts after genuine proposal/review/explicit demo acceptance above.
-- Long immutable histories and exact large balances are controlled fixture data.
insert into public.franchise_territory_versions(franchise_id,version,territory_code,name_fr,name_ar,scope_snapshot,effective_from,content_hash,created_by)
select franchise_id,n,'ACT204_1','Territoire historique '||n,'نطاق محفوظ','{}',now()-interval'1 day',content_hash,created_by from public.franchise_territory_versions cross join generate_series(2,1076)n where franchise_id=(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1')and version=1;
insert into public.franchise_mandate_versions(franchise_id,territory_version_id,economic_rule_version_id,version,mandate_status,rights_snapshot,obligations_snapshot,contract_snapshot,entry_fee_minor,entry_fee_mode,entry_fee_term_months,franchisee_share_bps,neoxa_share_bps,matricia_share_bps,distribution_basis,effective_from,effective_until,content_hash,created_by)
select franchise_id,territory_version_id,economic_rule_version_id,n,'PROPOSED',rights_snapshot,obligations_snapshot,contract_snapshot,entry_fee_minor,entry_fee_mode,entry_fee_term_months,franchisee_share_bps,neoxa_share_bps,matricia_share_bps,distribution_basis,effective_from,effective_until,content_hash,created_by from public.franchise_mandate_versions cross join generate_series(3,377)n where id=(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1');
insert into public.franchise_invitations(franchise_id,invited_email,expires_at)select (select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),'history204-'||n||'@example.invalid',now()+interval'1 day'from generate_series(1,1001)n;
