select private.grant_franchise_role_assignment_v1('c2040000-0000-4000-8000-000000000003','FRANCHISE_OWNER',(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE2'),'a2040000-0000-4000-8000-000000000003');
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);set local role authenticated;
