select is((select jsonb_array_length(value->'ts')from activation_results where kind='SNAPSHOT'),1076,'all territory versions beyond 1000 are returned');
select is((select jsonb_array_length(value->'ms')from activation_results where kind='SNAPSHOT'),377,'all mandate versions beyond legacy 300 limit are returned');
select is((select jsonb_array_length(value->'ins')from activation_results where kind='SNAPSHOT'),1002,'all invitations beyond PostgREST page limit are returned');
select is((select jsonb_array_length(value->'fs')from activation_results where kind='SNAPSHOT'),1,'scoped snapshot contains exact franchise only');
select is((select value->'ledgers'->0->>'amount_minor'from activation_results where kind='SNAPSHOT'),'9007199254740993','large money is preserved as exact decimal text');
