select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.franchise_governance_dashboard_snapshot((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE2'))$$,'42501','FRANCHISE_DASHBOARD_SCOPE_DENIED','sibling mandate is denied before projections');
