insert into public.franchise_territory_versions(franchise_id,version,territory_code,name_fr,name_ar,scope_snapshot,effective_from,content_hash,created_by)
select franchise_id,n,'ACT204_1','Territoire historique '||n,'نطاق محفوظ','{}',now()-interval'1 day',content_hash,created_by from public.franchise_territory_versions cross join generate_series(1077,20001)n where franchise_id=(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1')and version=1;
set local role authenticated;
select throws_ok($$select public.franchise_governance_dashboard_snapshot((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'))$$,'54000','FRANCHISE_DASHBOARD_SNAPSHOT_BUDGET_EXCEEDED','oversized history fails explicitly instead of appearing complete');
